function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3600)}
function parseApiResponse(path,res,text){
  const raw=String(text||'').trim();
  let data=null;
  try{data=raw?JSON.parse(raw):{ok:res.ok}}catch(_err){
    const fallback=raw||res.statusText||String(res.status||'');
    const error=res.status===404
      ? `接口不存在或服务未刷新：${path} 返回 ${fallback}。请刷新页面或重启 mmz config web。`
      : `接口返回了非 JSON 响应：${fallback}`;
    return {ok:false,error,http_status:res.status,raw_response:raw};
  }
  if(data&&typeof data==='object')return data;
  return {ok:res.ok,value:data};
}
async function api(path,body){
  let res;
  try{
    res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})});
  }catch(err){
    return {ok:false,error:`请求失败：${err&&err.message?err.message:String(err||'无法连接 WebUI 服务')}`};
  }
  const text=await res.text();
  const data=parseApiResponse(path,res,text);
  if(data.ok===undefined)data.ok=res.ok;
  if(!res.ok){data.ok=false;data.http_status=res.status;data.error=data.error||res.statusText||`HTTP ${res.status}`}
  return data;
}
